import base64,zlib,os
f_dashboard_html=""
with open("/var/www/luxe-talent/dist/dashboard.html","wb") as f: f.write(zlib.decompress(base64.b64decode(f_dashboard_html)))
print("dashboard.html:",len(zlib.decompress(base64.b64decode(f_dashboard_html))),"bytes")
f_performers_php=""
with open("/var/www/luxe-talent/dist/api/performers.php","wb") as f: f.write(zlib.decompress(base64.b64decode(f_performers_php)))
print("performers.php:",len(zlib.decompress(base64.b64decode(f_performers_php))),"bytes")
for f in ["/var/www/luxe-talent/dist/dashboard.html","/var/www/luxe-talent/dist/api/performers.php"]: os.system("chown apache:apache "+f)
print("Done!")